/* pre-dug holes from a hundred years of campers */
const preHoles=[];
for(let k=0;k<40000&&preHoles.length<3000;k++){
  const a=rng()*Math.PI*2,dd=Math.pow(rng(),1.6)*EDGE*1.35,x=r1(Math.cos(a)*dd),z=r1(20+Math.sin(a)*dd);
  if(Math.max(Math.abs(x),Math.abs(z))>EDGE-8||inCamp(x,z)||nearCampZone(x,z)||(z>12&&z<70&&Math.abs(x)<30))continue;
  if(holeNear(x,z,3.4))continue;
  preHoles.push(addHole({x,z,d:FIVE_FT,pre:true}));
}

